    if (modelError) {
      clearError();
      if (modelError.isRejection) return { state, verdict: 'rejected', reason: null }; // v1-style gated no-op
      throw new Error(`action raised: ${modelError.message}`);
    }
    return { state: snapshot(), verdict: 'accepted', reason: null };
  };

