          next.orders = set(model, order, { req: 'none', status: reserved ? 'confirmed' : 'rejected' });
        } else if (o.status === 'cancelling') {
          next.orders = set(model, order, { req: 'none', status: 'cancelled', rel: reserved ? o.qty : 0 });
        } else {
          next.orders = set(model, order, { req: 'none' });
        }
        unchanged('available', 'reserved');
      },
      // The inventory receives Release { qty }.
      DELIVER_RELEASE: (model) => ({ order }, { reject, next }) => {
        const o = model.orders[order];
        if (o.rel === 0) return reject('no-release-in-transit');
        next.reserved = model.reserved - o.rel;
        next.available = model.available + o.rel;
        next.orders = set(model, order, { rel: 0 });
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  PLACE: (data = {}) => intents.PLACE(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
  RESTOCK: (data = {}) => intents.RESTOCK(data),
  DELIVER_RESERVE: (data = {}) => intents.DELIVER_RESERVE(data),
  DELIVER_ANSWER: (data = {}) => intents.DELIVER_ANSWER(data),
  DELIVER_RELEASE: (data = {}) => intents.DELIVER_RELEASE(data),
};

module.exports = { instance, init, actions, getState, setState };

