'use strict';
// NEGATIVE CONTROL for spec/orders.spec.cjs: identical except that a cancelling
// order answered Reserved becomes cancelled WITHOUT sending a Release.
// The model check and the trace replay must both reject this mutant.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const IDS = ['A', 'B', 'C'];
const CAPACITY = 3;
const NONE = { status: 'none', qty: 0, req: 'none', rel: 0 };

const INITIAL_STATE = {
  available: 1,
  reserved: 0,
  orders: { A: { ...NONE }, B: { ...NONE }, C: { ...NONE } },
};

const orderDomain = IDS.map((order) => ({ order }));
const orderSchema = { order: { type: 'string' } };
const set = (model, id, patch) => ({ ...model.orders, [id]: { ...model.orders[id], ...patch } });

const control = instance({
  initialState: JSON.parse(JSON.stringify(INITIAL_STATE)),
  component: {
    modelShape: {
      available: { type: 'number' },
      reserved: { type: 'number' },
      orders: { type: 'object' },
    },
    actions: {
      PLACE: {
        action: (data = {}) => ({ ...data }),
        schema: { order: { type: 'string' }, qty: { type: 'number' } },
        domain: IDS.flatMap((order) => [0, 1, 2, 3].map((qty) => ({ order, qty }))),
      },
      CANCEL: { action: (data = {}) => ({ ...data }), schema: orderSchema, domain: orderDomain },
      RESTOCK: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      DELIVER_RESERVE: { action: (data = {}) => ({ ...data }), schema: orderSchema, domain: orderDomain },
      DELIVER_ANSWER: { action: (data = {}) => ({ ...data }), schema: orderSchema, domain: orderDomain },
      DELIVER_RELEASE: { action: (data = {}) => ({ ...data }), schema: orderSchema, domain: orderDomain },
    },
    acceptors: {
      PLACE: (model) => ({ order, qty }, { reject, next, unchanged }) => {
        if (qty !== 1 && qty !== 2) return reject('bad-qty');
        if (model.orders[order].status !== 'none') return reject('order-exists');
        next.orders = set(model, order, { status: 'pending', qty, req: 'Reserve' });
        unchanged('available', 'reserved');
      },
      CANCEL: (model) => ({ order }, { reject, next, unchanged }) => {
        const o = model.orders[order];
        if (o.status === 'confirmed') {
          next.orders = set(model, order, { status: 'cancelled', rel: o.qty });
        } else if (o.status === 'pending') {
          next.orders = set(model, order, { status: 'cancelling' });
        } else {
          return reject(o.status === 'none' ? 'no-such-order' : 'not-cancellable');
        }
        unchanged('available', 'reserved');
      },
      RESTOCK: (model) => (_p, { reject, next, unchanged }) => {
        if (model.available + model.reserved >= CAPACITY) return reject('inventory-full');
        next.available = model.available + 1;
        unchanged('reserved', 'orders');
      },
      DELIVER_RESERVE: (model) => ({ order }, { reject, next }) => {
        const o = model.orders[order];
        if (o.req !== 'Reserve') return reject('no-reserve-in-transit');
        if (model.available >= o.qty) {
          next.available = model.available - o.qty;
          next.reserved = model.reserved + o.qty;
          next.orders = set(model, order, { req: 'Reserved' });
        } else {
          next.available = model.available;
          next.reserved = model.reserved;
          next.orders = set(model, order, { req: 'OutOfStock' });
        }
      },
      DELIVER_ANSWER: (model) => ({ order }, { reject, next, unchanged }) => {
        const o = model.orders[order];
        if (o.req !== 'Reserved' && o.req !== 'OutOfStock') return reject('no-answer-in-transit');
        const reserved = o.req === 'Reserved';
        if (o.status === 'pending') {
          next.orders = set(model, order, { req: 'none', status: reserved ? 'confirmed' : 'rejected' });
        } else if (o.status === 'cancelling') {
          next.orders = set(model, order, { req: 'none', status: 'cancelled', rel: 0 }); // MUTATION
        } else {
          next.orders = set(model, order, { req: 'none' });
        }
        unchanged('available', 'reserved');
      },
      DELIVER_RELEASE: (model) => ({ order }, { reject, next }) => {
        const o = model.orders[order];
        if (o.rel === 0) return reject('no-release-in-transit');
        next.reserved = model.reserved - o.rel;
        next.available = model.available + o.rel;
        next.orders = set(model, order, { rel: 0 });
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  PLACE: (data = {}) => intents.PLACE(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
  RESTOCK: (data = {}) => intents.RESTOCK(data),
  DELIVER_RESERVE: (data = {}) => intents.DELIVER_RESERVE(data),
  DELIVER_ANSWER: (data = {}) => intents.DELIVER_ANSWER(data),
  DELIVER_RELEASE: (data = {}) => intents.DELIVER_RELEASE(data),
};

module.exports = { instance, init, actions, getState, setState };

