// Rules the brief requires, over the spec's state (spec/orders.spec.cjs).
const CAPACITY = 3;
const orders = (s) => Object.values(s.orders);
const placed = (s) => orders(s).filter((o) => o.status !== 'none');
const quiescent = (s) => orders(s).every((o) => o.req === 'none' && o.rel === 0);
const confirmedUnits = (s) => orders(s).filter((o) => o.status === 'confirmed').reduce((n, o) => n + o.qty, 0);
// Units held for each order: confirmed, or answered Reserved but not yet read, or released but not yet received.
const heldUnits = (s) => orders(s).reduce((n, o) =>
  n + (o.status === 'confirmed' ? o.qty : 0) + (o.req === 'Reserved' ? o.qty : 0) + o.rel, 0);
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);

export const stateInvariants = [
  { name: 'stock-non-negative', pred: (s) => s.available >= 0 && s.reserved >= 0 },
  { name: 'capacity', pred: (s) => s.available + s.reserved <= CAPACITY },
  { name: 'qty-is-1-or-2', pred: (s) => placed(s).every((o) => o.qty === 1 || o.qty === 2) },
  { name: 'units-accounted-for', pred: (s) => s.reserved === heldUnits(s) },
  { name: 'quiescent-reserved-equals-confirmed', pred: (s) => !quiescent(s) || s.reserved === confirmedUnits(s) },
  { name: 'confirmed-has-units-reserved', pred: (s) => orders(s).every((o) => o.status !== 'confirmed' || (o.req === 'none' && o.rel === 0)) },
  { name: 'rejected-holds-nothing', pred: (s) => orders(s).every((o) => o.status !== 'rejected' || (o.req === 'none' && o.rel === 0)) },
  { name: 'waiting-orders-await-an-answer', pred: (s) => orders(s).every((o) => !['pending', 'cancelling'].includes(o.status) || o.req !== 'none') },
  { name: 'cancelled-is-answered', pred: (s) => orders(s).every((o) => o.status !== 'cancelled' || o.req === 'none') },
];

export const transitionInvariants = [
  {
    name: 'units-only-added-by-restock',
    pred: (pre, action, _d, post) => {
      const before = pre.available + pre.reserved, after = post.available + post.reserved;
      return action === 'RESTOCK' ? after === before || after === before + 1 : after === before;
    },
  },
  {
    name: 'bad-qty-changes-nothing',
    pred: (pre, action, d, post) => action !== 'PLACE' || d.qty === 1 || d.qty === 2 || same(pre, post),
  },
  {
    name: 'place-on-existing-order-changes-nothing',
    pred: (pre, action, d, post) => action !== 'PLACE' || pre.orders[d.order].status === 'none' || same(pre, post),
  },
  {
    name: 'terminal-statuses-are-final',
    pred: (pre, _a, _d, post) => Object.keys(pre.orders).every((id) =>
      !['rejected', 'cancelled'].includes(pre.orders[id].status) || post.orders[id].status === pre.orders[id].status),
  },
  {
    name: 'qty-fixed-once-placed',
    pred: (pre, _a, _d, post) => Object.keys(pre.orders).every((id) =>
      pre.orders[id].status === 'none' || post.orders[id].qty === pre.orders[id].qty),
  },
  {
    name: 'cancel-refused-unless-pending-or-confirmed',
    pred: (pre, action, d, post) => action !== 'CANCEL' || ['pending', 'confirmed'].includes(pre.orders[d.order].status) || same(pre, post),
  },
];

export default { stateInvariants, transitionInvariants };

