    stock.reserved -= qty;
    stock.available += qty;
  };

  // An order's handlers: the answer to its Reserve.
  const onAnswer = (id: string, reserved: boolean): void => {
    const order = orders.get(id);
    if (!order) return;
    if (order.status === 'pending') {
