import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('initial state', async () => {
  const h = await createHost();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
  assert.deepEqual(await h.inFlight(), []);
  assert.equal(await h.order('a'), null);
});

test('place, confirm, cancel', async () => {
  const h = await createHost();
  assert.deepEqual(await h.place('a', 1), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'pending', qty: 1 });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual({ ...msgs[0], id: undefined }, { id: undefined, from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 1 } });
  await h.deliver(msgs[0].id);
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1 });
  const [ans] = await h.inFlight();
  assert.deepEqual([ans.from, ans.to, ans.action, ans.data], ['inventory', 'a', 'Reserved', {}]);
  await h.deliverAll();
  assert.equal((await h.order('a'))!.status, 'confirmed');
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.equal((await h.order('a'))!.status, 'cancelled');
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1 });
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
  assert.equal((await h.cancel('a')).ok, false);
});

test('out of stock rejects', async () => {
  const h = await createHost();
  await h.place('a', 2);
  await h.deliverAll();
  assert.equal((await h.order('a'))!.status, 'rejected');
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
  assert.equal((await h.cancel('a')).ok, false);
});

test('refusals', async () => {
  const h = await createHost();
  for (const q of [0, 3, 1.5, -1, NaN]) assert.equal((await h.place('a', q)).ok, false);
  assert.equal((await h.place('a', '1' as unknown as number)).ok, false);
  assert.equal(await h.order('a'), null);
  await h.place('a', 1);
  assert.equal((await h.place('a', 2)).ok, false);
  assert.equal((await h.cancel('zz')).ok, false);
  assert.equal((await h.inFlight()).length, 1);
});

test('restock capacity', async () => {
  const h = await createHost();
  assert.equal((await h.restock()).ok, true);
  assert.equal((await h.restock()).ok, true);
  const r = await h.restock();
  assert.equal(r.ok, false);
  assert.deepEqual(await h.stock(), { available: 3, reserved: 0 });
  await h.place('a', 2);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 2 });
  assert.equal((await h.restock()).ok, false);
});

test('cancel pending, answer Reserved: units go back', async () => {
  const h = await createHost();
  await h.place('a', 1);
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.equal((await h.order('a'))!.status, 'cancelling');
  assert.equal((await h.cancel('a')).ok, false);
  const [reserve] = await h.inFlight();
  await h.deliver(reserve.id);
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1 });
  const [answer] = await h.inFlight();
  await h.deliver(answer.id);
  assert.equal((await h.order('a'))!.status, 'cancelled');
  const [release] = await h.inFlight();
  assert.deepEqual([release.from, release.to, release.action, release.data], ['a', 'inventory', 'Release', { qty: 1 }]);
  await h.deliver(release.id);
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
});

test('cancel pending, answer OutOfStock', async () => {
  const h = await createHost();
  await h.place('a', 2);
  await h.cancel('a');
  await h.deliverAll();
  assert.equal((await h.order('a'))!.status, 'cancelled');
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
});

test('competing orders, any delivery order', async () => {
  const h = await createHost();
  await h.restock();
  await h.place('a', 1);
  await h.place('b', 2);
  const msgs = await h.inFlight();
  const b = msgs.find((m) => m.from === 'b')!;
  await h.deliver(b.id);
  await h.deliverAll();
  assert.equal((await h.order('b'))!.status, 'confirmed');
  assert.equal((await h.order('a'))!.status, 'rejected');
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
});

test('an order named inventory', async () => {
  const h = await createHost();
  await h.place('inventory', 1);
  await h.deliverAll();
  assert.equal((await h.order('inventory'))!.status, 'confirmed');
  await h.cancel('inventory');
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
});

test('expire a confirmed order', async () => {
  const h = await createHost();
  await h.place('a', 1);
  assert.equal((await h.expire('a')).ok, false); // pending
  await h.deliverAll();
  assert.deepEqual(await h.expire('a'), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'expired', qty: 1 });
  const [release] = await h.inFlight();
  assert.deepEqual([release.from, release.to, release.action, release.data], ['a', 'inventory', 'Release', { qty: 1 }]);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
  assert.equal((await h.expire('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.place('a', 1)).ok, false);
  assert.equal((await h.order('a'))!.status, 'expired');
});

test('expire refused for other statuses and unknown orders', async () => {
  const h = await createHost();
  assert.equal((await h.expire('zz')).ok, false);
  await h.place('r', 2);
  await h.deliverAll();
  assert.equal((await h.expire('r')).ok, false); // rejected
  await h.place('c', 1);
  await h.cancel('c');
  assert.equal((await h.expire('c')).ok, false); // cancelling
  await h.deliverAll();
  assert.equal((await h.expire('c')).ok, false); // cancelled
  assert.deepEqual(await h.inFlight(), []);
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0 });
});

test('fresh systems are independent', async () => {
  const h1 = await createHost();
  await h1.place('a', 1);
  const h2 = await createHost();
  assert.equal(await h2.order('a'), null);
  assert.deepEqual(await h2.inFlight(), []);
});

