// Captures traces from src/host.impl.ts through its public interface, projected
// onto the spec's observable state, one NDJSON file per scenario under spec/traces/.
// Run: node spec/capture.ts
import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import createHost from '../src/host.impl.ts';
import type { Host, Message } from '../host.ts';

const IDS = ['A', 'B', 'C'];
const DELIVER: Record<string, string> = {
  Reserve: 'DELIVER_RESERVE', Reserved: 'DELIVER_ANSWER', OutOfStock: 'DELIVER_ANSWER', Release: 'DELIVER_RELEASE',
};

const orderOf = (m: Message): string => (m.action === 'Reserved' || m.action === 'OutOfStock' ? m.to : m.from);

async function project(h: Host) {
  const msgs = await h.inFlight();
  const orders: Record<string, unknown> = {};
  for (const id of IDS) {
    const o = await h.order(id);
    const mine = msgs.filter((m) => orderOf(m) === id);
    const req = mine.find((m) => m.action !== 'Release')?.action ?? 'none';
    const rel = mine.filter((m) => m.action === 'Release').reduce((n, m) => n + Number(m.data.qty), 0);
    orders[id] = { status: o ? o.status : 'none', qty: o ? o.qty : 0, req, rel };
  }
  const { available, reserved } = await h.stock();
  return { orders, available, reserved };
}

// A tiny deterministic PRNG so the corpus is reproducible.
function rng(seed: number) {
  let s = seed >>> 0;
  return () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 2 ** 32; };
}
const pick = <T>(r: () => number, xs: T[]): T => xs[Math.floor(r() * xs.length)];

async function scenario(seed: number, steps: number): Promise<string[]> {
  const r = rng(seed);
  const h = await createHost();
  const lines: string[] = [];
  for (let i = 0; i < steps; i++) {
    const pre = await project(h);
    const msgs = await h.inFlight();
    const kind = r();
    let action: string, data: Record<string, unknown>;
    if (kind < 0.45 && msgs.length) {
      const m = pick(r, msgs);
      action = DELIVER[m.action]; data = { order: orderOf(m) };
      await h.deliver(m.id);
    } else if (kind < 0.7) {
      action = 'PLACE'; data = { order: pick(r, IDS), qty: pick(r, [0, 1, 2, 3]) };
      await h.place(data.order as string, data.qty as number);
    } else if (kind < 0.8) {
      action = 'CANCEL'; data = { order: pick(r, IDS) };
      await h.cancel(data.order as string);
    } else if (kind < 0.89) {
      action = 'EXPIRE'; data = { order: pick(r, IDS) };
      await h.expire(data.order as string);
    } else if (kind < 0.96) {
      action = 'RESTOCK'; data = {};
      await h.restock();
    } else {
      // a delivery with nothing of that kind in transit: a no-op window
      action = pick(r, ['DELIVER_RESERVE', 'DELIVER_ANSWER', 'DELIVER_RELEASE']); data = { order: pick(r, IDS) };
      const m = msgs.find((x) => orderOf(x) === data.order && DELIVER[x.action] === action);
      if (m) await h.deliver(m.id);
    }
    lines.push(JSON.stringify({ pre, action, data, post: await project(h) }));
  }
  return lines;
}

const dir = new URL('./traces/', import.meta.url);
rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });
for (let seed = 1; seed <= 60; seed++) {
  writeFileSync(new URL(`s${seed}.ndjson`, dir), (await scenario(seed, 40)).join('\n') + '\n');
}
console.log('captured 60 traces');

