test('reduce a confirmed order of 2, then cancel', async () => {
  const h = await createHost();
  await h.restock();
  await h.place('a', 2);
  assert.equal((await h.reduce('a')).ok, false); // pending
  await h.deliverAll();
  assert.deepEqual(await h.reduce('a'), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'confirmed', qty: 1 });
  const [release] = await h.inFlight();
  assert.deepEqual([release.from, release.to, release.action, release.data], ['a', 'inventory', 'Release', { qty: 1 }]);
  assert.equal((await h.reduce('a')).ok, false); // now 1 unit
  await h.cancel('a'); // a second Release in flight before the first lands
  assert.equal((await h.inFlight()).length, 2);
  await h.deliverAll();
  assert.equal((await h.order('a'))!.status, 'cancelled');
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0, open: true });
});

test('reduce then expire; reduce refused otherwise', async () => {
  const h = await createHost();
  await h.restock();
  assert.equal((await h.reduce('zz')).ok, false);
  await h.place('a', 2);
  await h.deliverAll();
  await h.reduce('a');
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 1, open: true });
  await h.expire('a');
