// Replay-only conformance check: each captured window { pre, action, data, post }
// is replayed against each given spec (init; setState(pre); action(data)) and
// getState() compared with post. verify.mjs does the same and then also runs the
// model check; this skips the model check so the mutants replay quickly.
// Run: node spec/replay.mjs <spec.cjs>...
import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { loadSpec, stable } from '../tools/polygraph/scripts/load-spec.mjs';

const dir = new URL('./traces/', import.meta.url);
const windows = readdirSync(dir).filter((f) => f.endsWith('.ndjson')).flatMap((f) =>
  readFileSync(new URL(f, dir), 'utf8').split('\n').filter(Boolean).map((l) => ({ file: f, ...JSON.parse(l) })));

let failedSpecs = 0;
for (const path of process.argv.slice(2)) {
  const spec = loadSpec(join(process.cwd(), path));
  let bad = 0, first = null;
  for (const w of windows) {
    let got;
    try {
      spec.init(); spec.setState(w.pre); spec.actions[w.action](w.data);
      got = JSON.parse(JSON.stringify(spec.getState()));
    } catch (e) { got = { error: String(e && e.message) }; }
    if (stable(got) !== stable(w.post)) { bad++; first ??= { ...w, got }; }
  }
  console.log(`${path}: ${windows.length - bad}/${windows.length} windows consistent`);
  if (first) console.log(`  first disagreement (${first.file}): ${first.action} ${JSON.stringify(first.data)}`);
  if (bad) failedSpecs++;
}
process.exitCode = failedSpecs ? 1 : 0;

